import { USERS, expect, test } from "../../fixtures";

test("wrong password is rejected with invalid_credentials", { tag: "@AUTH-02" }, async ({ request }) => {
  const response = await request.post("/api/auth/login", {
    data: { email: USERS.member, password: "wrong-password" },
  });
  const body = await response.text();

  expect(response.status(), body).toBe(401);
  const parsed = JSON.parse(body) as { error?: { code?: string } };
  expect(parsed.error?.code, body).toBe("invalid_credentials");
});
